+      {
+        text: "📞 帮它找主人",
+        hint: "贴寻狗启事",
+        apply: (st) => {
+          st.needs.fatigue = Math.min(100, st.needs.fatigue + 8);
+          st.status.fame = Math.min(100, st.status.fame + 2);
+          StateManager.addMessage(
+            "📞 主人找到了！你好人有好报，心情不错。",
+            "success",
+          );
