+    else if (key === "fatigue") parts.push(`疲劳${val < 0 ? val : "+" + val}`);
+    else if (typeof val === "number")
+      parts.push(`${key}${val > 0 ? "+" + val : val}`);
+  }
+  return parts.join(", ");
+}
