+  }
+
+  const profitStr =
+    profit >= 0
+      ? `📈 盈利 ¥${Math.round(profit).toLocaleString()}`
+      : `📉 亏损 ¥${Math.abs(Math.round(profit)).toLocaleString()}`;
+  StateManager.addMessage(
+    `💰 卖出 ${symbol} ×${shares}股，¥${revenue.toLocaleString()}。${profitStr}`,
+    profit >= 0 ? "success" : "warning",
