+function getSkillName(key) {
+  const names = {
+    cooking: "烹饪",
+    repair: "维修",
+    coding: "编程",
+    english: "英语",
+    driving: "驾驶",
+    sales: "销售",
+    management: "管理",
+    accounting: "会计",
+    electrician: "电工",
+    welding: "焊接",
+  };
+  return names[key] || key;
+}
